-- Auto-generated seed data for structures and personnel
ON DUPLICATE KEY UPDATE
    name = VALUES(name),
    address = VALUES(address);

ON DUPLICATE KEY UPDATE
    full_name = VALUES(full_name),
    email = VALUES(email),
    phone = VALUES(phone),
    role = VALUES(role),
    structure_id = VALUES(structure_id),
    updated_at = VALUES(updated_at);
